export {
  IMPORT_URL,
  SIGNUP_URL,
  importPlaybookUrl,
  IMPORT_TEMPLATE_ID,
  ALT_TEMPLATE_ID,
} from "@/lib/ballet-links";

export const DEFAULT_DEMO_URL = "https://ballet.dev/api/demo/enrich";

export const STEP_TITLES = [
  "Searching live people data for your lead",
  "Crawling the company website",
  "Scoring ICP fit and writing your opener",
] as const;

/** Conversion links for Ballet starters. */

export const SIGNUP_URL =
  "https://app.ballet.dev/signup?utm_source=v0&utm_medium=template&utm_campaign=lead-enrichment";

export const IMPORT_TEMPLATE_ID = "salesforce-lead-enrichment";
export const ALT_TEMPLATE_ID = "inbound-lead-slack-alert";

export const IMPORT_URL =
  "https://app.ballet.dev/import?repo=brainfish-ai/ballet-templates&path=templates/salesforce-lead-enrichment&ref=main";

export function importPlaybookUrl(templateId: string = IMPORT_TEMPLATE_ID) {
  const q = new URLSearchParams({
    repo: "brainfish-ai/ballet-templates",
    path: `templates/${templateId}`,
    ref: "main",
    utm_source: "v0",
    utm_medium: "template",
    utm_campaign: "lead-enrichment",
  });
  return `https://app.ballet.dev/import?${q.toString().replace(/%2F/g, "/")}`;
}

/**
 * Triggers a Ballet playbook from a Next.js route handler.
 *
 * Verified against Ballet public docs and live API error responses:
 * - Docs: https://ballet.dev/docs/articles/how-do-i-authenticate-with-the-ballet-api-tWaqCPLyGT
 * - Docs: https://ballet.dev/docs/articles/how-do-i-run-a-playbook-over-the-rest-api-KQIz0apagm
 * - Live probe without token → 401 {"error":"Authentication required"}
 * - Live probe with invalid Bearer → 401 {"error":"Invalid or revoked API token"}
 *
 * Real mode (both env vars set):
 *   POST BALLET_WORKFLOW_URL
 *   Authorization: Bearer <BALLET_API_KEY>   // workspace token, mt_live_…
 *   Content-Type: application/json
 *   Body for execute/run URLs: { "input": { …lead fields } }
 *   Body for webhook URLs (/webhooks/): the lead fields object itself
 *
 * Prefer:
 *   BALLET_WORKFLOW_URL=https://api.ballet.dev/api/playbooks/<PLAYBOOK_ID>/execute
 * which streams SSE and ends with a run_stop event containing output.
 *
 * Mock mode (either env var missing): returns mockFn() so the demo works offline.
 *
 * Note: Ballet docs name the token BALLET_API_TOKEN. This starter uses BALLET_API_KEY
 * as the env var name for the same Bearer token value.
 */
export type BalletTriggerResult<T> = {
  mock: boolean;
  success: boolean;
  output: T;
  runId?: string;
  error?: string;
};

function isWebhookUrl(url: string) {
  return /\/webhooks\//i.test(url);
}

async function readExecuteStream(res: Response): Promise<{
  success: boolean;
  output: unknown;
  runId?: string;
}> {
  const contentType = res.headers.get("content-type") ?? "";
  if (!contentType.includes("text/event-stream")) {
    const json = (await res.json().catch(() => ({}))) as Record<string, unknown>;
    if (!res.ok) {
      throw new Error(
        String(json.error ?? json.message ?? `Ballet request failed (${res.status})`),
      );
    }
    return {
      success: true,
      output: (json.output as unknown) ?? json,
      runId: typeof json.runId === "string" ? json.runId : undefined,
    };
  }

  const reader = res.body?.getReader();
  if (!reader) throw new Error("Ballet stream had no body");
  const decoder = new TextDecoder();
  let buffer = "";
  let result: { success: boolean; output: unknown; runId?: string } | undefined;

  while (true) {
    const { value, done } = await reader.read();
    if (done) break;
    buffer += decoder.decode(value, { stream: true });
    const frames = buffer.split("\n\n");
    buffer = frames.pop() ?? "";
    for (const frame of frames) {
      const line = frame.split("\n").find((l) => l.startsWith("data:"));
      if (!line) continue;
      const event = JSON.parse(line.slice(5).trim()) as {
        type?: string;
        run?: { success?: boolean; output?: unknown; id?: string; runId?: string };
      };
      if (event.type === "run_stop" && event.run) {
        result = {
          success: Boolean(event.run.success),
          output: event.run.output,
          runId: event.run.runId ?? event.run.id,
        };
      }
    }
  }

  if (!result) throw new Error("Ballet stream ended without run_stop");
  return result;
}

export async function triggerBalletWorkflow<T>(
  input: Record<string, unknown>,
  mockFn: () => T,
): Promise<BalletTriggerResult<T>> {
  const apiKey = process.env.BALLET_API_KEY?.trim();
  const workflowUrl = process.env.BALLET_WORKFLOW_URL?.trim();

  if (!apiKey || !workflowUrl) {
    return { mock: true, success: true, output: mockFn() };
  }

  try {
    const webhook = isWebhookUrl(workflowUrl);
    const res = await fetch(workflowUrl, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${apiKey}`,
        "Content-Type": "application/json",
        Accept: "application/json, text/event-stream",
      },
      body: JSON.stringify(webhook ? input : { input }),
    });

    const parsed = await readExecuteStream(res);
    return {
      mock: false,
      success: parsed.success,
      output: (parsed.output as T) ?? mockFn(),
      runId: parsed.runId,
    };
  } catch (err) {
    return {
      mock: false,
      success: false,
      output: mockFn(),
      error: err instanceof Error ? err.message : "Ballet request failed",
    };
  }
}

/** Parse Ballet demo/run SSE frames into typed events. */

export type BalletSseEvent =
  | { type: "run_start"; data: Record<string, unknown> }
  | {
      type: "run_delta";
      data: {
        delta?:
          | string
          | {
              type?: string;
              message?: string;
              phase?: string;
              [key: string]: unknown;
            };
        message?: string;
        phase?: string;
      };
    }
  | {
      type: "step_start";
      data: {
        index?: number;
        step?: {
          id?: string;
          description?: string;
          friendlyMessage?: string;
        };
      };
    }
  | {
      type: "step_delta";
      data: {
        stepId?: string;
        delta?:
          | string
          | {
              type?: string;
              text?: string;
              message?: string;
              [key: string]: unknown;
            };
      };
    }
  | {
      type: "step_stop";
      data: {
        stepId?: string;
        result?: {
          status?: string;
          durationMs?: number;
          output?: unknown;
        };
      };
    }
  | {
      type: "run_stop";
      data: {
        run?: {
          status?: string;
          output?: unknown;
          success?: boolean;
        };
      };
    }
  | { type: "error"; data: Record<string, unknown> }
  | { type: "ping"; data: Record<string, unknown> }
  | { type: "unknown"; name: string; data: Record<string, unknown> };

export function parseSseChunk(
  buffer: string,
): { events: BalletSseEvent[]; rest: string } {
  const events: BalletSseEvent[] = [];
  const parts = buffer.split("\n\n");
  const rest = parts.pop() ?? "";

  for (const frame of parts) {
    if (!frame.trim()) continue;
    let eventName = "message";
    const dataLines: string[] = [];
    for (const line of frame.split("\n")) {
      if (line.startsWith("event:")) eventName = line.slice(6).trim();
      else if (line.startsWith("data:")) dataLines.push(line.slice(5).trim());
      else if (line.startsWith(":")) continue;
    }
    const raw = dataLines.join("\n");
    let data: Record<string, unknown> = {};
    if (raw) {
      try {
        data = JSON.parse(raw) as Record<string, unknown>;
      } catch {
        data = { raw };
      }
    }
    switch (eventName) {
      case "run_start":
        events.push({ type: "run_start", data });
        break;
      case "run_delta":
        events.push({
          type: "run_delta",
          data: data as Extract<BalletSseEvent, { type: "run_delta" }>["data"],
        });
        break;
      case "step_start":
        events.push({
          type: "step_start",
          data: data as Extract<BalletSseEvent, { type: "step_start" }>["data"],
        });
        break;
      case "step_delta":
        events.push({
          type: "step_delta",
          data: data as Extract<BalletSseEvent, { type: "step_delta" }>["data"],
        });
        break;
      case "step_stop":
        events.push({
          type: "step_stop",
          data: data as Extract<BalletSseEvent, { type: "step_stop" }>["data"],
        });
        break;
      case "run_stop":
        events.push({
          type: "run_stop",
          data: data as Extract<BalletSseEvent, { type: "run_stop" }>["data"],
        });
        break;
      case "error":
        events.push({ type: "error", data });
        break;
      case "ping":
        events.push({ type: "ping", data });
        break;
      default:
        events.push({ type: "unknown", name: eventName, data });
    }
  }

  return { events, rest };
}

export async function* iterateBalletSse(
  res: Response,
): AsyncGenerator<BalletSseEvent> {
  const reader = res.body?.getReader();
  if (!reader) throw new Error("Demo stream had no body");
  const decoder = new TextDecoder();
  let buffer = "";
  while (true) {
    const { value, done } = await reader.read();
    if (done) break;
    buffer += decoder.decode(value, { stream: true });
    const parsed = parseSseChunk(buffer);
    buffer = parsed.rest;
    for (const event of parsed.events) yield event;
  }
  if (buffer.trim()) {
    const parsed = parseSseChunk(buffer + "\n\n");
    for (const event of parsed.events) yield event;
  }
}

export function deltaMessage(delta: unknown): string | undefined {
  if (!delta) return undefined;
  if (typeof delta === "string") return delta;
  if (typeof delta === "object") {
    const d = delta as Record<string, unknown>;
    for (const key of ["message", "text", "content", "phase"]) {
      if (typeof d[key] === "string" && d[key]) return String(d[key]);
    }
    if (typeof d.type === "string" && typeof d.value === "string") return d.value;
  }
  return undefined;
}

