    useChat<EnrichUIMessage>({
      transport,
      onData: (part) => {
        if (part.type === "data-locked") {
          const data = (part as { data?: EnrichDataParts["locked"] }).data;
          setLocked(true);
          setLockMessage(
            data?.message ||
              "You used your free live run. Import the playbook to run it on your own leads.",
